def polynomial_to_string(n: int, coeffs: list) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - i
        # Determine the sign
        if terms:
            sign = '+' if coeff > 0 else '-'
        else:
            sign = '' if coeff > 0 else '-'

        abs_coeff = abs(coeff)

        # Determine the coefficient part
        if degree == 0:
            coeff_part = str(abs_coeff)
        else:
            if abs_coeff == 1:
                coeff_part = ''
            else:
                coeff_part = str(abs_coeff)

        # Determine the variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'

        term = sign + coeff_part + var_part
        terms.append(term)

    if not terms:
        return '0'

    return ''.join(terms)
