def decode(encoded: str, original: str, message: str) -> str:
    # Build mapping from encoded to original
    mapping = {}
    for enc, orig in zip(encoded, original):
        if enc in mapping:
            if mapping[enc] != orig:
                return "Failed"
        else:
            mapping[enc] = orig

    # Check if all letters are represented in the mapping
    # The problem says "not all letters are represented in the mapping"
    # We need to check if the mapping covers all 26 letters? Or all letters in the message?
    # Let's check: the example "AA" -> "AB" fails because A maps to both A and B.
    # The second example works.
    # Let's check if the mapping has all 26 letters.
    # Actually, let's check if the mapping is a bijection (one-to-one) and covers all letters.
    # But the problem says "not all letters are represented in the mapping".
    # Let's check if the set of keys in mapping has size 26.
    if len(mapping) != 26:
        return "Failed"

    # Also check that the mapping is one-to-one (no two encoded letters map to the same original letter)
    # Actually, the problem says "If a contradiction is found during mapping construction"
    # Contradiction could mean: same encoded letter maps to different original letters (already checked)
    # Or different encoded letters map to the same original letter? Let's check.
    # In a cipher, it should be a permutation, so it should be bijective.
    # Let's check if the values are all unique.
    if len(set(mapping.values())) != 26:
        return "Failed"

    # Now decode the message
    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded)
